package com.trimtime.appointment;
import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.*; import java.util.*;
public final class AppointmentDtos { private AppointmentDtos(){} public record CreateRequest(@NotNull Long salonId,List<Long> serviceIds,Long serviceId,List<Long> addonIds,@NotNull @FutureOrPresent LocalDate date,@NotNull LocalTime startTime){public List<Long> selectedServiceIds(){var selected=serviceIds==null?List.<Long>of():serviceIds.stream().filter(Objects::nonNull).distinct().toList();return selected.isEmpty()&&serviceId!=null?List.of(serviceId):selected;}} public record Response(String bookingReference,LocalDate date,LocalTime startTime,LocalTime endTime,String salonName,String barberName,String serviceName,String addonSummary,int durationMinutes,BigDecimal totalPrice,AppointmentStatus status){static Response from(Appointment a){return new Response(a.getBookingReference(),a.getStartAt().toLocalDate(),a.getStartAt().toLocalTime(),a.getEndAt().toLocalTime(),a.getSalon().getName(),a.getBarber().getDisplayName(),a.getServiceName(),a.getAddonSummary(),a.getDurationMinutes(),a.getTotalPrice(),a.getStatus());}} }
